namespace sv_474027783c91475483b09ec9cc0b36f9.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_474027783c91475483b09ec9cc0b36f9.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var stepNumber = i + 1;
            var isCompleted = CompletedSteps.Contains(stepIndex);
            var isCurrent = stepIndex == CurrentStep;
            var cssClass = isCurrent ? "step current" : isCompleted ? "step completed" : "step future";

            <li class="@cssClass">
                @if (isCompleted && !isCurrent)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <span class="step-content">
                        <span class="step-icon">@stepNumber</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };
}

@namespace sv_474027783c91475483b09ec9cc0b36f9.Components.Pages.Apply

<div class="step-panel">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" value="@FullName" @oninput="e => FullNameChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        @if (_errors.ContainsKey("FullName"))
        {
            <span class="field-error">@_errors["FullName"]</span>
        }
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" value="@Email" @oninput="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        @if (_errors.ContainsKey("Email"))
        {
            <span class="field-error">@_errors["Email"]</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" value="@Phone" @oninput="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        @if (_errors.ContainsKey("Phone"))
        {
            <span class="field-error">@_errors["Phone"]</span>
        }
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" rows="3" value="@Address" @oninput="e => AddressChanged.InvokeAsync(e.Value?.ToString() ?? "")">@Address</textarea>
        @if (_errors.ContainsKey("Address"))
        {
            <span class="field-error">@_errors["Address"]</span>
        }
    </div>

    @if (!string.IsNullOrEmpty(_generalError))
    {
        <div class="general-error">@_generalError</div>
    }

    <div class="step-buttons">
        <button class="btn-next" @onclick="HandleNext" disabled="@_validating">
            @(_validating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";

    [Parameter] public EventCallback<string> FullNameChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback<string> AddressChanged { get; set; }

    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private Dictionary<string, string> _errors = new();
    private string _generalError = "";
    private bool _validating;

    private async Task HandleNext()
    {
        _errors.Clear();
        _generalError = "";

        if (string.IsNullOrWhiteSpace(FullName))
            _errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email))
            _errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone))
            _errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address))
            _errors["Address"] = "Address is required.";

        if (_errors.Count > 0) return;

        _validating = true;
        try
        {
            var emailValid = await ValidateEmail(Email);
            if (!emailValid)
            {
                _errors["Email"] = "This email address is not valid.";
                return;
            }
            await OnNext.InvokeAsync();
        }
        catch
        {
            _generalError = "An error occurred while validating. Please try again.";
        }
        finally
        {
            _validating = false;
        }
    }
}

@namespace sv_474027783c91475483b09ec9cc0b36f9.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Company" @oninput="e => CompanyChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Title" @oninput="e => TitleChanged.InvokeAsync(e.Value?.ToString() ?? "")" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => StartDateChanged.InvokeAsync(DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")))" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")" disabled="@IsCurrent"
                   @onchange="e => EndDateChanged.InvokeAsync(string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!))" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="e => IsCurrentChanged.InvokeAsync((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @oninput="e => DescriptionChanged.InvokeAsync(e.Value?.ToString() ?? "")">@Description</textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }

    [Parameter] public EventCallback<string> CompanyChanged { get; set; }
    [Parameter] public EventCallback<string> TitleChanged { get; set; }
    [Parameter] public EventCallback<DateTime> StartDateChanged { get; set; }
    [Parameter] public EventCallback<DateTime?> EndDateChanged { get; set; }
    [Parameter] public EventCallback<bool> IsCurrentChanged { get; set; }
    [Parameter] public EventCallback<string> DescriptionChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_474027783c91475483b09ec9cc0b36f9.Components.Pages.Apply

<div class="step-panel">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var idx = i;
        var entry = Entries[idx];
        <WorkEntryForm Index="idx"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       CanRemove="@(Entries.Count > 1)"
                       CompanyChanged="(v) => UpdateEntry(idx, e => e.Company = v)"
                       TitleChanged="(v) => UpdateEntry(idx, e => e.Title = v)"
                       StartDateChanged="(v) => UpdateEntry(idx, e => e.StartDate = v)"
                       EndDateChanged="(v) => UpdateEntry(idx, e => e.EndDate = v)"
                       IsCurrentChanged="(v) => UpdateEntry(idx, e => { e.IsCurrent = v; if (v) e.EndDate = null; })"
                       DescriptionChanged="(v) => UpdateEntry(idx, e => e.Description = v)"
                       OnRemove="() => RemoveEntry(idx)" />
    }

    <button class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_error))
    {
        <div class="general-error">@_error</div>
    }

    <div class="step-buttons">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string _error = "";

    private void UpdateEntry(int index, Action<WorkEntryModel> update)
    {
        update(Entries[index]);
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        _error = "";
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _error = "Each position requires at least a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_474027783c91475483b09ec9cc0b36f9.Components.Pages.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
