    [Parameter] public EventCallback<string> CompanyChanged { get; set; }
    [Parameter] public EventCallback<string> TitleChanged { get; set; }
    [Parameter] public EventCallback<DateTime> StartDateChanged { get; set; }
    [Parameter] public EventCallback<DateTime?> EndDateChanged { get; set; }
    [Parameter] public EventCallback<bool> IsCurrentChanged { get; set; }
    [Parameter] public EventCallback<string> DescriptionChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}
"}

{"path": "/tmp/sv-474027783c91475483b09ec9cc0b36f9/Components/Pages/Apply/WorkHistoryStep.razor", "file_text": "@namespace sv_474027783c91475483b09ec9cc0b36f9.Components.Pages.Apply

<div class="step-panel">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var idx = i;
        var entry = Entries[idx];
        <WorkEntryForm Index="idx"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       CanRemove="@(Entries.Count > 1)"
                       CompanyChanged="(v) => UpdateEntry(idx, e => e.Company = v)"
                       TitleChanged="(v) => UpdateEntry(idx, e => e.Title = v)"
                       StartDateChanged="(v) => UpdateEntry(idx, e => e.StartDate = v)"
                       EndDateChanged="(v) => UpdateEntry(idx, e => e.EndDate = v)"
                       IsCurrentChanged="(v) => UpdateEntry(idx, e => { e.IsCurrent = v; if (v) e.EndDate = null; })"
                       DescriptionChanged="(v) => UpdateEntry(idx, e => e.Description = v)"
                       OnRemove="() => RemoveEntry(idx)" />
    }

    <button class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_error))
    {
        <div class="general-error">@_error</div>
    }

    <div class="step-buttons">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string _error = "";

    private void UpdateEntry(int index, Action<WorkEntryModel> update)
    {
        update(Entries[index]);
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        _error = "";
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _error = "Each position requires at least a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}
"}

