namespace sv_474027783c91475483b09ec9cc0b36f9.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@namespace sv_474027783c91475483b09ec9cc0b36f9.Components.Pages.Apply
@using sv_474027783c91475483b09ec9cc0b36f9.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                              FullNameChanged="(v) => _fullName = v"
                              EmailChanged="(v) => _email = v"
                              PhoneChanged="(v) => _phone = v"
                              AddressChanged="(v) => _address = v"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="() => AdvanceStep(0)" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="() => AdvanceStep(1)"
                             OnBack="() => GoToStep(0)" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            OnNext="() => AdvanceStep(2)"
                            OnBack="() => GoToStep(1)" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             CoverLetterChanged="(v) => _coverLetter = v"
                             OnNext="() => AdvanceStep(3)"
                             OnBack="() => GoToStep(2)" />
            break;
        case 4:
            <ReviewStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                        WorkEntries="_workEntries" References="_references" CoverLetter="@_coverLetter"
                        OnBack="() => GoToStep(3)"
                        OnEditStep="GoToStep"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private HashSet<int> _completedSteps = new();

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> _workEntries = new() { new() };

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> _references = new() { new(), new() };

    // Step 4 state
    private string _coverLetter = "";

    private void AdvanceStep(int completedStep)
    {
        _completedSteps.Add(completedStep);
        _currentStep = completedStep + 1;
    }

    private void GoToStep(int step)
    {
        if (step <= _currentStep || _completedSteps.Contains(step))
            _currentStep = step;
    }

    private async Task<int> SubmitAsync()
    {
        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var workEntries = _workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList();
        var work = new WorkHistory(workEntries);
        var refs = _references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

        var application = new JobApplication(personal, work, refs, _coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

/* Job Application Form Styles */
.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
    position: relative;
}

.step-list::before {
    content: '';
    position: absolute;
    top: 16px;
    left: 5%;
    right: 5%;
    height: 2px;
    background: #ddd;
    z-index: 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    z-index: 1;
    flex: 1;
}

.step-content,
.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: default;
    padding: 0;
    font: inherit;
}

.step-button {
    cursor: pointer;
}

.step-button:hover .step-icon {
    background: #16a085;
    transform: scale(1.1);
}

.step-icon {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.85rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
    transition: all 0.2s;
}

.step.current .step-icon {
    background: #3498db;
    color: white;
}

.step.completed .step-icon {
    background: #27ae60;
    color: white;
}

.step.future .step-icon {
    background: #ecf0f1;
    color: #95a5a6;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #7f8c8d;
    max-width: 80px;
}

.step.current .step-label {
    color: #3498db;
    font-weight: 600;
}

.step.completed .step-label {
    color: #27ae60;
}

/* Step Panel */
.step-panel {
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

.step-panel h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #2c3e50;
    border-bottom: 2px solid #3498db;
    padding-bottom: 0.5rem;
}

.step-description {
    color: #7f8c8d;
    margin-bottom: 1.5rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #34495e;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #dce1e6;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #3498db;
    box-shadow: 0 0 0 2px rgba(52, 152, 219, 0.15);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.5rem;
    font-weight: 400 !important;
    font-size: 0.85rem !important;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Field Errors */
.field-error {
    display: block;
    color: #e74c3c;
    font-size: 0.8rem;
    margin-top: 0.25rem;
}

.general-error {
    background: #fdf0ef;
    border: 1px solid #e74c3c;
    border-radius: 4px;
    padding: 0.75rem 1rem;
    color: #c0392b;
    margin: 1rem 0;
    font-size: 0.9rem;
}

/* Character Count */
.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #95a5a6;
    margin-top: 0.25rem;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #ecf0f1;
}

.btn-next,
.btn-submit {
    background: #3498db;
    color: white;
    border: none;
    padding: 0.7rem 2rem;
    border-radius: 4px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
    margin-left: auto;
}

.btn-next:hover,
.btn-submit:hover {
    background: #2980b9;
}

.btn-next:disabled,
.btn-submit:disabled {
    background: #bdc3c7;
    cursor: not-allowed;
}

.btn-back {
    background: transparent;
    color: #7f8c8d;
    border: 1px solid #bdc3c7;
    padding: 0.7rem 2rem;
    border-radius: 4px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-back:hover {
    color: #2c3e50;
    border-color: #7f8c8d;
}

.btn-submit {
    background: #27ae60;
}

.btn-submit:hover {
    background: #219a52;
}

.btn-secondary {
    background: transparent;
    color: #3498db;
    border: 1px dashed #3498db;
    padding: 0.6rem 1.2rem;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-top: 1rem;
    transition: all 0.2s;
}

.btn-secondary:hover {
    background: #ebf5fb;
}

.btn-remove {
    background: transparent;
    color: #e74c3c;
    border: none;
    font-size: 0.85rem;
    cursor: pointer;
    padding: 0.3rem 0.6rem;
}

.btn-remove:hover {
    text-decoration: underline;
}

.btn-link {
    background: none;
    border: none;
    color: #3498db;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
}

.btn-link:hover {
    color: #2980b9;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #ecf0f1;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    color: #2c3e50;
}

/* Review Step */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #ecf0f1;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h3 {
    margin: 0 0 0.75rem 0;
    color: #2c3e50;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #7f8c8d;
}

.review-section dd {
    margin: 0;
    color: #2c3e50;
}

.review-work-entry,
.review-reference {
    margin-bottom: 0.75rem;
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 4px;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    line-height: 1.6;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 2rem;
}

.confirmation h3 {
    color: #27ae60;
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.confirmation p {
    font-size: 1.1rem;
    color: #2c3e50;
}

/* Responsive */
@media (max-width: 600px) {
    .form-row {
        grid-template-columns: 1fr;
    }

    .step-label {
        font-size: 0.65rem;
    }

    .step-icon {
        width: 28px;
        height: 28px;
        font-size: 0.75rem;
    }
}

