{"file_text": "@page "/apply"
@rendermode InteractiveServer
@namespace sv_474027783c91475483b09ec9cc0b36f9.Components.Pages.Apply
@using sv_474027783c91475483b09ec9cc0b36f9.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                              FullNameChanged="(v) => _fullName = v"
                              EmailChanged="(v) => _email = v"
                              PhoneChanged="(v) => _phone = v"
                              AddressChanged="(v) => _address = v"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="() => AdvanceStep(0)" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="() => AdvanceStep(1)"
                             OnBack="() => GoToStep(0)" />
            break;
        case 2:
            <ReferencesStep References="_references"
                            OnNext="() => AdvanceStep(2)"
                            OnBack="() => GoToStep(1)" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             CoverLetterChanged="(v) => _coverLetter = v"
                             OnNext="() => AdvanceStep(3)"
                             OnBack="() => GoToStep(2)" />
            break;
        case 4:
            <ReviewStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                        WorkEntries="_workEntries" References="_references" CoverLetter="@_coverLetter"
                        OnBack="() => GoToStep(3)"
                        OnEditStep="GoToStep"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private HashSet<int> _completedSteps = new();

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> _workEntries = new() { new() };

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> _references = new() { new(), new() };

    // Step 4 state
    private string _coverLetter = "";

    private void AdvanceStep(int completedStep)
    {
        _completedSteps.Add(completedStep);
        _currentStep = completedStep + 1;
    }

    private void GoToStep(int step)
    {
        if (step <= _currentStep || _completedSteps.Contains(step))
            _currentStep = step;
    }

    private async Task<int> SubmitAsync()
    {
        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var workEntries = _workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList();
        var work = new WorkHistory(workEntries);
        var refs = _references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

        var application = new JobApplication(personal, work, refs, _coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}
